htmlform.script:
if(jQuery){
$j(document).ready(function(){
$j(".checkboxGroup").each(function(){
var group = $j(this);
var uncheckAll = function(){
group.find("input[type$='checkbox']").attr("checked",false);
group.find("input[type$='checkbox']").change();
}
var uncheckRadioAndAll = function(){
group.find("#checkboxAll,#checkboxRadio").find("input[type$='checkbox']").attr("checked",false);
group.find("#checkboxAll,#checkboxRadio").find("input[type$='checkbox']").change();
}
group.find("#checkboxRadio").find("input[type$='checkbox']").click(function(){
uncheckAll();
$j(this).siblings("input[type$='checkbox']").attr("checked",false);
$j(this).attr("checked",true);
$j(this).change();
});
});

$j('input[type=radio]').change(function() {
// Find the associated textarea based on the name attribute of the radio button
var textarea = $j(this).closest('td').find('textarea');

// Update the textarea value based on the selected radio button value
if ($j(this).val() === 'normal') {
textarea.val('Normal');
} else if ($j(this).val() === 'abnormal') {
textarea.val('Abnormal because:');
}
});
});
}

var $acts = jQuery;
$acts(document).ready(function () {
    var selector = $acts('#actsCategorySelector');
    var search = $acts('#actsSearch');
    var info = $acts('#actsSearchInfo');
    var container = $acts('#actsByCategoryContainer');
    var categories = container.find('.actsCategory');
    var items = container.find('.actItem');

    function hasValue(div) {
        var entered = $acts(div).find('input[type=text]').filter(function () {
            return String($acts(this).val()).trim() !== '';
        }).length;
        if (entered !== 0) { return true; }
        /* view mode: saved values are shown as text */
        var saved = $acts(div).find('.value').filter(function () {
            return $acts(this).text().replace(/_/g, '').trim() !== '';
        }).length;
        return saved !== 0;
    }

    function show(id) {
        categories.hide();
        if (id === '__filled') {
            categories.filter(function () { return hasValue(this); }).show();
        } else if (id !== '__none') {
            $acts('#' + id).show();
        }
    }

    function markFilled() {
        categories.each(function () {
            var option = selector.find('option[value=' + this.id + ']');
            var label = option.attr('data-label') || option.text();
            option.attr('data-label', label);
            option.text(hasValue(this) ? label + ' \u2714' : label);
        });
    }

    function runSearch() {
        var words = String(search.val()).toLowerCase().split(' ').filter(function (w) { return w !== ''; });
        if (words.length === 0) {
            /* no search: back to the chosen category */
            items.show();
            info.text('');
            show(selector.val());
            return;
        }
        var found = 0;
        items.each(function () {
            var name = $acts(this).find('.actName').text().toLowerCase();
            var match = words.every(function (w) { return name.indexOf(w) !== -1; });
            $acts(this).toggle(match);
            if (match) { found = found + 1; }
        });
        categories.each(function () {
            var cat = $acts(this);
            cat.toggle(cat.find('.actItem').filter(function () { return $acts(this).css('display') !== 'none'; }).length !== 0);
        });
        info.text(found === 0 ? 'No act found' : found + ' act(s) found in all categories');
    }

    selector.change(function () {
        search.val('');
        runSearch();
    });
    search.bind('keyup change', runSearch);
    /* Enter in the search box must not submit the form */
    search.bind('keydown', function (e) { if (e.which === 13) { return false; } });
    container.find('input').bind('change keyup', markFilled);

    /* edit/view: open the categories that already have saved acts */
    if (categories.filter(function () { return hasValue(this); }).length !== 0) {
        selector.val('__filled');
    } else {
        selector.val('__none');
    }
    show(selector.val());
    markFilled();
});
